            if grid[r][0] != bg_color:
                sep_row = r
                sep_color = grid[r][0]
                break

    # Find shape color (color that's not bg and not separator)
    shape_color = None
    for c in counts.keys():
        if c != bg_color and c != sep_color:
            shape_color = c
            break

    if shape_color is None:
        return grid

    # Get original shape cells
    shape_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == shape_color]
    if not shape_cells:
        return grid

    min_r = min(r for r, c in shape_cells)
    max_r = max(r for r, c in shape_cells)

    # Determine shift - make shape adjacent to separator
    if sep_row > max_r:
        # Separator below: move shape down so new bottom is at sep_row - 1
        new_bot = sep_row - 1
        shift = new_bot - max_r
    elif sep_row < min_r:
        # Separator above: move shape up so new top is at sep_row + 1
        new_top = sep_row + 1
        shift = new_top - min_r
    else:
        return grid

    # Build output grid filled with background color
    new_grid = [[bg_color for _ in range(w)] for _ in range(h)]

    # Copy separator row
    if sep_row >= 0:
        new_grid[sep_row] = [sep_color] * w

    # Fill vacated rows with 8s
    # Find rows that are in old shape span but not in new shape span
    vacated_rows = set(range(min_r, max_r + 1)) - set(range(min_r + shift, max_r + shift + 1))
    for r in sorted(vacated_rows):
        if 0 <= r < h:
            new_grid[r] = [8] * w

    # Place shape at new position
    for r, c in shape_cells:
        nr = r + shift
        if 0 <= nr < h and nr != sep_row:
            new_grid[nr][c] = shape_color

    return new_grid
